@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
:root{--ink:#f2eee0;--muted:#9ba39a;--faint:#65716a;--bg:#111714;--panel:#19211d;--line:#34423a;--gold:#e5bf74;--mint:#9ed3ac;--red:#db8878;--blue:#8ebbc5;--serif:'Playfair Display',Georgia,serif;--mono:'DM Mono',monospace;--sans:'DM Sans',Arial,sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#26372d 0%,#111714 58%);color:var(--ink);font-family:var(--sans);min-height:100vh;background-attachment:fixed}.game-shell{max-width:1180px;margin:0 auto;padding:0 28px 18px}.topbar{height:68px;display:flex;align-items:center;border-bottom:1px solid #354038;gap:24px}.brand{display:flex;gap:10px;align-items:center;min-width:215px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid #9c8050;color:var(--gold);font-size:19px;transform:rotate(45deg);border-radius:8px}.brand-mark:first-letter{transform:rotate(-45deg)}.brand-name{font:500 13px var(--mono);letter-spacing:.18em;color:#e9dfc9}.brand-sub{font:9px var(--mono);color:#829087;letter-spacing:.14em;margin-top:3px}.chapter{font:10px var(--mono);letter-spacing:.1em;color:#aab1a8;display:flex;align-items:center;gap:10px}.chapter b{color:#536058;font-weight:400}.chapter-dot{width:7px;height:7px;border-radius:50%;background:#c9a458;box-shadow:0 0 10px #d1a950}.icon-button{margin-left:auto;background:transparent;color:#c2c8bc;border:1px solid #4a574d;width:30px;height:30px;border-radius:50%;font:13px var(--mono);cursor:pointer}.icon-button:hover{border-color:var(--gold);color:var(--gold)}
.world-banner{height:154px;margin:19px 0 16px;position:relative;overflow:hidden;border:1px solid #435449;background:#1a2a27;display:flex;align-items:center}.world-art{position:absolute;inset:0;overflow:hidden;background:linear-gradient(180deg,#263945 0%,#435452 50%,#263b34 51%,#172522 100%)}.world-art:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(13,20,19,.05) 0%,rgba(15,21,19,.32) 33%,#17221f 70%,#17221f 100%)}.moon{position:absolute;left:8%;top:19px;width:50px;height:50px;background:#d3c899;border-radius:50%;box-shadow:0 0 32px #d4d1aa55}.mountains{position:absolute;left:0;right:0;bottom:35px;height:77px;background:#263a3a;clip-path:polygon(0 70%,10% 27%,15% 50%,25% 7%,36% 62%,46% 21%,56% 65%,67% 12%,78% 55%,88% 26%,100% 67%,100% 100%,0 100%);opacity:.85}.reeds{position:absolute;inset:62px 0 0;background:repeating-linear-gradient(86deg,transparent 0 47px,#172621 48px 50px,transparent 51px 67px),linear-gradient(0deg,#101d1a 0%,transparent 73%);opacity:.85}.bell-art{position:absolute;left:33%;top:57px;font-size:34px;color:#b29c67;transform:scaleX(1.3);text-shadow:0 2px 0 #333,0 0 15px #d7bc7355;z-index:1}.waterline{position:absolute;bottom:24px;left:0;right:0;height:2px;background:#9ab8a250;box-shadow:0 7px 0 #9ab8a21c,0 14px 0 #9ab8a215}.world-copy{position:relative;z-index:2;margin-left:40%;max-width:520px}.eyebrow{font:9px var(--mono);letter-spacing:.17em;color:#a9bdad}.world-copy h1{font:700 29px var(--serif);margin:7px 0 4px;letter-spacing:.01em}.world-copy p{font-size:12px;color:#b5c0b7;margin:0;max-width:430px}.world-stamp{position:absolute;left:22px;bottom:14px;z-index:2;border:1px solid #9d8b63;color:var(--gold);width:38px;height:43px;display:flex;flex-direction:column;justify-content:center;align-items:center;background:#15221ebd}.world-stamp span{font:17px var(--serif)}.world-stamp small{font:7px var(--mono);letter-spacing:.1em}.challenge-pill{position:absolute;z-index:2;right:17px;top:15px;background:#1a2522dd;border:1px solid #58665b;padding:7px 10px;font:8px var(--mono);letter-spacing:.12em;color:#c3d0c3}.pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:#e5bd69;margin-right:6px;box-shadow:0 0 8px #f4ca74}
.battlefield{background:linear-gradient(145deg,#1d2822,#17201c);border:1px solid #39483e;padding:15px 20px 11px;position:relative;box-shadow:0 12px 30px #0002}.battle-topline{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.14em;color:#9eaf9f;margin-bottom:11px}.battle-topline span:last-child{color:var(--gold)}.tiny-spark{font-style:normal;color:var(--gold)}.opponent-row,.player-row{display:flex;align-items:center;gap:13px;max-width:680px;margin:0 auto}.avatar{width:43px;height:43px;border:1px solid #667166;display:grid;place-items:center;position:relative;flex:none;background:#27352e;box-shadow:inset 0 0 0 3px #1b2721}.avatar span{font-size:23px}.enemy-avatar{color:#d3a178;background:#382d28}.player-avatar{color:#a7d1b0;background:#24372c}.avatar i{position:absolute;right:-3px;bottom:-3px;width:10px;height:10px;border:2px solid #1b2520;border-radius:50%;background:#c87968}.player-avatar i{background:#92bd98}.life-block{flex:1;max-width:390px}.life-heading{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.12em;color:#b3beb2}.life-heading strong{font:600 16px var(--serif);color:#f0e9d8}.life-track{height:5px;background:#3a463d;margin-top:5px;overflow:hidden}.life-fill{height:100%;width:100%;background:#d17966;transition:width .35s ease}.player-life .life-fill{background:#93c69c}.life-note{font:8px var(--mono);color:#7f8e83;letter-spacing:.11em;margin-top:5px}.bell-counter{margin-left:auto;display:flex;align-items:center;gap:8px;min-width:150px}.bell-symbol{font-size:22px;color:#c6a665}.bell-counter b{font:10px var(--mono);color:#e2c47f;letter-spacing:.06em}.bell-counter small{display:block;color:#849188;font:7px var(--mono);letter-spacing:.09em;margin-top:2px}.toll-dots{display:flex;gap:4px;margin-left:5px}.toll-dots i{width:7px;height:7px;border:1px solid #73715d;border-radius:50%}.toll-dots i.rung{background:#d1a354;box-shadow:0 0 7px #c79f58}.enemy-board,.player-board{min-height:87px;display:flex;align-items:center;justify-content:center;gap:9px;padding:8px 0}.field-divider{height:13px;border-top:1px solid #3a493e;text-align:center;position:relative;color:#637368;font:7px var(--mono);letter-spacing:.2em}.field-divider span{position:relative;top:-6px;background:#19231e;padding:0 12px}.player-board{min-height:89px}.combat-tip{text-align:center;border-top:1px solid #303d34;padding-top:8px;margin-top:4px;font:9px var(--mono);letter-spacing:.05em;color:#849488;min-height:26px}.combat-tip span{color:var(--gold)}.combat-tip b{color:#c8d8c8;font-weight:500}.mana-block{display:flex;align-items:center;gap:8px;min-width:145px;margin-left:auto}.mana-glyph{color:#92c3d0;font-size:20px;text-shadow:0 0 12px #80c6d266}.mana-block b{font:10px var(--mono);color:#b4d7dc}.mana-block small{display:block;font:7px var(--mono);color:#7f9494;letter-spacing:.1em;margin-top:2px}.mana-pips{display:flex;gap:3px;margin-left:3px}.mana-pips i{width:6px;height:12px;border:1px solid #4c7277;transform:skew(-12deg)}.mana-pips i.on{background:#8ac2cd;box-shadow:0 0 6px #8ac2cd66}
.creature{width:112px;height:66px;background:#202d26;border:1px solid #6e7c68;position:relative;display:grid;grid-template-columns:38px 1fr;align-items:center;padding:5px 7px;gap:6px;box-shadow:0 3px 0 #101714;cursor:default;transition:.15s}.creature:before{content:"";position:absolute;inset:3px;border:1px solid #35483a;pointer-events:none}.creature.enemy{border-color:#806557;background:#302822}.creature .creature-art{font-size:26px;text-align:center;filter:drop-shadow(0 2px 2px #0008)}.creature .creature-name{font:8px var(--mono);letter-spacing:.04em;color:#eee5d0;line-height:1.2}.creature .creature-type{font:7px var(--mono);color:#93aa94;margin-top:4px}.creature .stats{position:absolute;right:5px;bottom:-6px;background:#27372b;border:1px solid #8a9b70;padding:2px 5px;color:#e1d49e;font:9px var(--mono);min-width:27px;text-align:center}.creature.enemy .stats{border-color:#b17d66;color:#edc4a4}.creature.tapped{opacity:.55;transform:rotate(2deg);filter:saturate(.6)}.creature.selected{outline:2px solid var(--gold);outline-offset:2px;box-shadow:0 0 15px #dcbb6c55;cursor:pointer}.creature.can-attack{cursor:pointer}.empty-board{font:9px var(--mono);letter-spacing:.1em;color:#5e6d61;padding:10px}
.lower-panel{display:grid;grid-template-columns:minmax(0,1fr) 278px;gap:15px;margin-top:15px}.hand-section,.side-panel{background:#19221e;border:1px solid #39473d;padding:13px 15px}.section-heading{height:40px;display:flex;align-items:center;justify-content:space-between}.section-heading h2{font:600 16px var(--serif);margin:3px 0 0}.section-heading h2 span{font:10px var(--mono);color:#9eaf9f;margin-left:4px}.hand-hint{font:8px var(--mono);color:#7d8a80;letter-spacing:.06em}.hand-row{display:flex;gap:8px;overflow-x:auto;padding:7px 2px 5px;min-height:171px;scrollbar-color:#506252 #1c2821;scrollbar-width:thin}.card{width:105px;height:154px;flex:0 0 105px;border:1px solid #8a815f;background:#30382d;position:relative;padding:6px;cursor:pointer;transition:transform .15s,box-shadow .15s;box-shadow:0 4px 8px #0005;overflow:hidden;color:#f4ead4}.card:hover{transform:translateY(-5px);box-shadow:0 8px 14px #0008}.card.selected{transform:translateY(-8px);outline:2px solid var(--gold);box-shadow:0 0 16px #e8c87955}.card.unplayable{filter:saturate(.58);opacity:.83}.card-top{display:flex;justify-content:space-between;align-items:center;height:18px;font:8px var(--mono);letter-spacing:.04em}.cost-gem{display:grid;place-items:center;width:17px;height:17px;border-radius:50%;background:#8ac4c8;color:#14282a;font:700 9px var(--mono);box-shadow:0 0 7px #8ac4c855}.card-art{height:60px;margin:3px 0;background:linear-gradient(155deg,#57715c,#29372e 65%,#253b3a);display:grid;place-items:center;font-size:36px;border:1px solid #74826a;position:relative;overflow:hidden}.card-art:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#12191577,transparent 45%,#fff1)}.card.spell .card-art{background:radial-gradient(circle,#6a7485,#293743 72%)}.card-title{font:600 9px var(--serif);height:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-type{font:6px var(--mono);color:#b6c3a9;letter-spacing:.08em;text-transform:uppercase;margin-top:1px}.card-rule{font:7px var(--sans);line-height:1.2;color:#dbddcb;margin-top:4px;height:24px;overflow:hidden}.card-bottom{position:absolute;bottom:5px;left:7px;right:7px;display:flex;justify-content:space-between;align-items:center;font:7px var(--mono);color:#d3c795}.card-stats{border:1px solid #b5ad7f;padding:2px 4px;font-size:8px}.tag-echo{position:absolute;top:6px;right:26px;font:6px var(--mono);color:#b9a2d4;letter-spacing:.05em}.empty-hand{align-self:center;color:#718075;font:9px var(--mono);padding-left:10px}.side-panel{padding:14px 15px;position:relative}.side-title{display:flex;justify-content:space-between;align-items:center}.oath-icon{color:#ddbf7c;font-size:17px}.side-panel h3{font:600 18px var(--serif);margin:6px 0}.side-panel>p{font-size:10px;color:#a9b4a9;line-height:1.5;margin:0 0 12px}.toll-track{display:flex;justify-content:space-between;font:7px var(--mono);color:#89958b;letter-spacing:.06em}.toll-track span:last-child{color:#d48b77}.side-divider{height:1px;background:#354239;margin:12px 0}.echo-info{display:flex;gap:9px;align-items:flex-start}.echo-mark{width:25px;height:25px;display:grid;place-items:center;border:1px solid #716184;color:#c4addc;background:#292333;font-size:17px;flex:none}.echo-info b{font:8px var(--mono);letter-spacing:.1em;color:#cab6df}.echo-info p{font:9px var(--sans);color:#a7b0a7;line-height:1.35;margin:3px 0 0}.echo-info strong{color:#ded3ac;font-weight:600}.graveyard-row{display:flex;gap:8px;margin-top:13px}.grave-button,.end-turn{height:34px;cursor:pointer;font:8px var(--mono);letter-spacing:.08em}.grave-button{background:#222d27;border:1px solid #566257;color:#aeb9af;flex:1}.grave-button span{font-size:13px;margin-right:4px}.grave-button b{color:#d3bd81;margin-left:4px}.grave-button:hover{border-color:#a98c5c}.end-turn{background:#d0ad67;color:#1b211a;border:1px solid #e3c782;padding:0 12px;font-weight:500;box-shadow:0 2px 0 #846b3d}.end-turn span{font-size:14px;margin-left:6px}.end-turn:hover{background:#ebc97e}.end-turn:disabled{opacity:.45;cursor:not-allowed}footer{display:flex;justify-content:space-between;padding:12px 3px 0;color:#58665c;font:7px var(--mono);letter-spacing:.12em}.toast{position:fixed;left:50%;top:20px;transform:translate(-50%,-20px);background:#d8bc7c;color:#18211b;padding:10px 18px;border:1px solid #f1d895;font:10px var(--mono);letter-spacing:.05em;opacity:0;pointer-events:none;transition:.2s;z-index:10;box-shadow:0 5px 25px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#080d0bd9;display:grid;place-items:center;padding:18px}.modal-backdrop.hidden{display:none}.modal{position:relative;background:#1c2821;border:1px solid #65745f;padding:27px 30px;max-width:460px;width:100%;box-shadow:0 15px 55px #0009}.modal:before{content:"";position:absolute;inset:5px;border:1px solid #34463a;pointer-events:none}.modal-close{position:absolute;right:15px;top:10px;background:none;border:0;color:#bdc7ba;font-size:24px;cursor:pointer}.modal h2{font:700 25px var(--serif);margin:6px 0 15px}.modal-body{font-size:12px}.modal p{font-size:11px;color:#b2bdb2;line-height:1.65;margin:10px 0}.modal p b{color:#e5ca87}.modal-actions{margin-top:19px;text-align:right}.grave-list{display:grid;gap:7px;margin-top:13px}.grave-entry{display:flex;align-items:center;justify-content:space-between;background:#26332b;border:1px solid #4b5c4d;padding:8px;font-size:10px}.grave-entry button{background:#9c85b7;color:#201a27;border:0;padding:6px 8px;font:8px var(--mono);cursor:pointer}.grave-entry button:disabled{opacity:.4;cursor:not-allowed}.grave-empty{font:10px var(--mono);color:#839086;padding:15px;text-align:center}.game-over{text-align:center;padding:8px 0}.game-over .sigil{font-size:40px;color:var(--gold)}.game-over p{max-width:330px;margin:10px auto 0}.modal-actions .end-turn{min-width:110px}
@media (min-width:950px){.battlefield{padding-left:28px;padding-right:28px}.world-banner{height:164px}.lower-panel{grid-template-columns:minmax(0,1fr) 292px}.hand-section{padding:13px 18px}.card{width:108px;flex-basis:108px}}
@media (max-width:760px){.game-shell{padding:0 12px 15px}.topbar{height:58px}.brand{min-width:0}.brand-sub{font-size:7px}.brand-name{font-size:11px}.chapter{font-size:8px;margin-left:auto}.world-banner{height:143px;margin:12px 0}.world-copy{margin-left:31%;padding-right:10px}.world-copy h1{font-size:23px}.world-copy p{font-size:10px}.world-art:after{background:linear-gradient(90deg,transparent 0%,#17221fdd 75%,#17221f 100%)}.bell-art{left:24%}.world-stamp{left:12px}.battlefield{padding:12px 10px 8px}.opponent-row,.player-row{gap:8px}.avatar{width:35px;height:35px}.bell-counter{min-width:112px;gap:5px}.bell-counter small{font-size:6px}.toll-dots{gap:2px;margin-left:0}.life-note{font-size:7px}.mana-block{min-width:115px;gap:5px}.mana-pips{gap:2px}.enemy-board,.player-board{min-height:76px;gap:5px;overflow-x:auto;justify-content:flex-start}.creature{width:98px;flex:0 0 98px;height:61px;grid-template-columns:31px 1fr;padding:4px}.creature .creature-art{font-size:22px}.creature .creature-name{font-size:7px}.lower-panel{grid-template-columns:1fr;gap:10px;margin-top:10px}.side-panel{order:-1;padding:11px 13px}.side-panel>p{max-width:600px}.side-divider{margin:8px 0}.echo-info{max-width:450px}.graveyard-row{position:absolute;right:13px;bottom:11px;margin:0}.grave-button{display:none}.side-panel{padding-bottom:54px}.hand-section{padding:11px}.hand-row{min-height:165px}.card{width:100px;flex-basis:100px;height:148px}.hand-hint{font-size:7px}.section-heading h2{font-size:15px}.combat-tip{font-size:8px}footer{font-size:6px}.world-copy .eyebrow{font-size:8px}.challenge-pill{font-size:7px;right:8px;top:8px;padding:6px}.modal{padding:24px 20px}}
@media (max-width:390px){.chapter{font-size:7px;gap:5px}.brand{gap:7px}.brand-mark{width:29px;height:29px}.world-copy{margin-left:27%}.world-copy h1{font-size:20px}.bell-counter{min-width:95px}.bell-symbol{font-size:18px}.toll-dots i{width:6px;height:6px}.mana-block{min-width:100px}.mana-pips i{height:9px;width:5px}}

(() => {
  const cardBook = {
    reedling:{name:'Reedling',type:'creature',cost:1,power:1,hp:2,art:'♧',kind:'FEN FOLK',text:'A small light in a long dark.',echo:false},
    fenfox:{name:'Fen Fox',type:'creature',cost:1,power:2,hp:1,art:'⌁',kind:'WILD SPIRIT',text:'Quick as a ripple.',echo:false},
    mossback:{name:'Mossback',type:'creature',cost:2,power:2,hp:3,art:'♜',kind:'MARSH BEAST',text:'Patient. Then unstoppable.',echo:false},
    lanternmage:{name:'Lantern Mage',type:'creature',cost:3,power:2,hp:3,art:'♙',kind:'WANDERER',text:'On arrival: deal 1 to the Keeper.',echo:false,effect:'ping'},
    mourningstag:{name:'Mourning Stag',type:'creature',cost:3,power:3,hp:3,art:'♘',kind:'ECHO SPIRIT',text:'Echo — cast once more from your grave.',echo:true},
    bellroot:{name:'Bellroot Guardian',type:'creature',cost:4,power:3,hp:5,art:'♜',kind:'ANCIENT',text:'A wall grown from drowned stone.',echo:false},
    gloambolt:{name:'Gloam Bolt',type:'spell',cost:2,art:'ϟ',kind:'SPELL',text:'Deal 3 damage to the Keeper.',echo:false,effect:'bolt'},
    moonwater:{name:'Moonwater',type:'spell',cost:2,art:'◌',kind:'SPELL',text:'Restore 4 life to yourself.',echo:false,effect:'heal'},
    rootgrip:{name:'Root Grip',type:'spell',cost:1,art:'⌘',kind:'SPELL',text:'Deal 2 damage to an enemy creature.',echo:false,effect:'snare'},
    sunkenword:{name:'Sunken Word',type:'spell',cost:3,art:'✧',kind:'SPELL',text:'Deal 4 damage to the Keeper.',echo:false,effect:'word'}
  };
  const enemyBook = {
    mireling:{name:'Mireling',power:1,hp:2,art:'♧',kind:'BOG CRAWLER',cost:1},
    tollwraith:{name:'Toll Wraith',power:2,hp:2,art:'♙',kind:'DROWNED SPIRIT',cost:2},
    bogknight:{name:'Bog Knight',power:3,hp:3,art:'♜',kind:'FEN SENTINEL',cost:3},
    bellhound:{name:'Bell Hound',power:2,hp:4,art:'♞',kind:'RELIC HOUND',cost:3}
  };
  const deckList = ['reedling','reedling','reedling','fenfox','fenfox','fenfox','mossback','mossback','mossback','lanternmage','lanternmage','mourningstag','mourningstag','bellroot','gloambolt','gloambolt','moonwater','rootgrip','rootgrip','sunkenword'];
  const enemyList = ['mireling','mireling','tollwraith','mireling','bogknight','tollwraith','bellhound','mireling','bogknight','tollwraith','bellhound','bogknight'];
  const $ = id => document.getElementById(id);
  const state = {
    playerLife:20,enemyLife:24,turn:1,enemyTurns:0,playerMana:1,playerMaxMana:1,enemyMana:1,
    hand:[],deck:[],grave:[],echoed:[],allies:[],foes:[],selectedCard:null,selectedUnit:null,
    finished:false,phase:'player',tolls:0,log:[],toastTimer:null,modalMode:'',
    enemyDeck:[],enemyHand:[]
  };
  let nextId=1;
  function makeCard(key){return {...cardBook[key],key,id:nextId++,damage:0};}
  function makeEnemy(key){return {...enemyBook[key],key,id:nextId++,damage:0,ready:false};}
  function shuffle(arr){for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}return arr;}
  function init(){
    state.deck=shuffle(deckList.map(makeCard)); state.enemyDeck=shuffle([...enemyList]);
    const guaranteed=state.deck.findIndex(c=>c.cost<=2&&c.type==='creature');
    if(guaranteed>0){const [c]=state.deck.splice(guaranteed,1);state.hand.push(c);}
    while(state.hand.length<4) drawPlayer(false);
    state.enemyHand=state.enemyDeck.splice(0,3).map(k=>makeEnemy(k));
    render();
  }
  function drawPlayer(show=true){if(!state.deck.length){if(show)toast('Your library is empty.');return;}const c=state.deck.pop();state.hand.push(c);if(show)toast(`${c.name} drawn`);}
  function render(){
    $('enemyLifeText').textContent=state.enemyLife;$('playerLifeText').textContent=state.playerLife;
    $('enemyLifeBar').style.width=`${Math.max(0,state.enemyLife/24*100)}%`;$('playerLifeBar').style.width=`${Math.max(0,state.playerLife/20*100)}%`;
    $('turnLabel').textContent=state.phase==='player'?`YOUR TURN · ${state.turn}`:`KEEPER'S TURN · ${state.turn}`;
    $('tollCount').textContent=`${state.tolls} / 3`;
    [...$('tollDots').children].forEach((d,i)=>d.classList.toggle('rung',i<state.tolls));
    $('tollNote').textContent=state.tolls===2?'ONE MORE TOLL ENDS THE CHALLENGE':'THE THIRD TOLL MUST NOT RING';
    $('manaText').textContent=`${state.playerMana} / ${state.playerMaxMana}`;
    $('manaPips').innerHTML=Array.from({length:6},(_,i)=>`<i class="${i<state.playerMana?'on':''}"></i>`).join('');
    $('handCount').textContent=state.hand.length;$('graveCount').textContent=state.grave.length;$('deckCount').textContent=`LIBRARY ${state.deck.length}`;
    $('playerStatus').textContent=state.finished?(state.enemyLife<=0?'THE FEN FALLS SILENT':'THE TIDE TAKES YOU'):state.selectedUnit?'READY TO STRIKE':'DRAW A CARD · FIND YOUR LINE';
    $('enemyBoard').innerHTML=state.foes.length?state.foes.map(u=>unitMarkup(u,true)).join(''):'<div class="empty-board">NO SHADOWS IN THE WATER</div>';
    $('playerBoard').innerHTML=state.allies.length?state.allies.map(u=>unitMarkup(u,false)).join(''):'<div class="empty-board">THE WATER WAITS FOR YOUR FIRST ALLY</div>';
    $('handRow').innerHTML=state.hand.length?state.hand.map(c=>cardMarkup(c,false)).join(''):'<div class="empty-hand">Your hand is empty.</div>';
    $('handHint').textContent=state.selectedCard?`${cardBook[state.selectedCard.key].name} · ${state.selectedCard.echo?'ECHO ':''}${state.selectedCard.cost} MANA`:'Choose a card to inspect';
    $('endTurn').disabled=state.finished||state.phase!=='player';
    document.querySelectorAll('.card').forEach(el=>el.addEventListener('click',()=>selectCard(Number(el.dataset.id))));
    document.querySelectorAll('.creature.can-attack').forEach(el=>el.addEventListener('click',()=>selectUnit(Number(el.dataset.id))));
    updateCombatTip();
  }
  function unitMarkup(u,enemy){
    const selected=!enemy&&state.selectedUnit===u.id;
    const canAttack=!enemy&&state.phase==='player'&&u.ready&&!state.finished;
    const max=u.hp||u.maxHp||u.power;
    const actualHp=Math.max(0,max-(u.damage||0));
    return `<div class="creature ${enemy?'enemy':''} ${!u.ready?'tapped':''} ${selected?'selected':''} ${canAttack?'can-attack':''}" data-id="${u.id}" title="${u.name} · ${u.power}/${actualHp}"><div class="creature-art">${u.art}</div><div><div class="creature-name">${u.name}</div><div class="creature-type">${u.kind}</div></div><div class="stats">${u.power}/${actualHp}</div></div>`;
  }
  function cardMarkup(c,grave){const data=cardBook[c.key];const selected=state.selectedCard?.id===c.id;const affordable=state.phase==='player'&&state.playerMana>=c.cost+(grave?1:0)&&!state.finished;
    return `<div class="card ${c.type==='spell'?'spell':''} ${selected?'selected':''} ${affordable?'':'unplayable'}" data-id="${c.id}" title="${data.text}"><div class="card-top"><span>${c.type==='creature'?'CREATURE':'SPELL'}</span><span class="cost-gem">${c.cost+(grave?1:0)}</span></div>${c.echo?'<span class="tag-echo">ECHO</span>':''}<div class="card-art">${c.art}</div><div class="card-title">${c.name}</div><div class="card-type">${c.kind}</div><div class="card-rule">${c.text}</div><div class="card-bottom"><span>${grave?'REPLAY':'FEN DECK'}</span>${c.type==='creature'?`<span class="card-stats">${c.power}/${c.hp}</span>`:''}</div></div>`;
  }
  function updateCombatTip(){const tip=$('combatTip');if(state.finished){tip.innerHTML=`<span>✦</span> ${state.enemyLife<=0?'THE SUNKEN BELL IS SILENT':'THE THIRD TOLL HAS FALLEN'}`;return;}
    if(state.phase!=='player'){tip.innerHTML='<span>✦</span> The Keeper is moving through the reeds…';return;}
    if(state.selectedCard){const c=state.selectedCard;const cost=c.cost+(c.echo?1:0);tip.innerHTML=`<span>✦</span> ${c.name} · ${cost} mana <button class="tip-button" id="playSelected" ${state.playerMana<cost?'disabled':''}>${c.type==='spell'?'CAST':'PLAY'} CARD</button><button class="tip-cancel" id="cancelSelect">CANCEL</button>`;$('playSelected')?.addEventListener('click',playSelected);$('cancelSelect')?.addEventListener('click',()=>{state.selectedCard=null;render();});return;}
    if(state.selectedUnit){const u=state.allies.find(x=>x.id===state.selectedUnit);tip.innerHTML=`<span>✦</span> ${u?.name||'Creature'} selected <button class="tip-button" id="attackSelected">ATTACK</button><button class="tip-cancel" id="cancelSelect">CANCEL</button>`;$('attackSelected')?.addEventListener('click',playerAttack);$('cancelSelect')?.addEventListener('click',()=>{state.selectedUnit=null;render();});return;}
    tip.innerHTML='<span>✦</span> Select a ready creature, then choose <b>ATTACK</b>.';
  }
  function selectCard(id){if(state.finished||state.phase!=='player')return;const c=state.hand.find(x=>x.id===id);if(!c)return;state.selectedCard=state.selectedCard?.id===id?null:c;state.selectedUnit=null;render();}
  function selectUnit(id){if(state.finished||state.phase!=='player')return;const u=state.allies.find(x=>x.id===id);if(!u?.ready)return;state.selectedUnit=state.selectedUnit===id?null:id;state.selectedCard=null;render();}
  function playSelected(){const c=state.selectedCard;if(!c||state.phase!=='player'||state.finished)return;if(state.playerMana<c.cost){toast('Not enough marsh mana.');return;}
    state.playerMana-=c.cost;state.hand=state.hand.filter(x=>x.id!==c.id);state.selectedCard=null;
    if(c.type==='creature'){const unit={...c,ready:false,damage:0,maxHp:c.hp};state.allies.push(unit);if(c.effect==='ping')state.enemyLife-=1;toast(`${c.name} joins your side`);}
    else{resolveSpell(c);state.grave.push(c);}
    checkGameOver();render();
  }
  function resolveSpell(c){if(c.effect==='bolt'){state.enemyLife-=3;toast('Gloam Bolt hits the Keeper for 3.');}
    if(c.effect==='word'){state.enemyLife-=4;toast('The Sunken Word tears through the veil.');}
    if(c.effect==='heal'){const healed=Math.min(4,20-state.playerLife);state.playerLife+=healed;toast(`Moonwater restores ${healed} life.`);}
    if(c.effect==='snare'){
      if(!state.foes.length){state.enemyLife-=2;toast('No enemy to snare — 2 damage to the Keeper.');}
      else{const target=state.foes.slice().sort((a,b)=>a.hp-a.damage-(b.hp-b.damage))[0];target.damage+=2;toast(`${target.name} is caught in roots.`);cleanDead();}
    }
  }
  function playerAttack(){const a=state.allies.find(x=>x.id===state.selectedUnit);if(!a||!a.ready||state.finished)return;state.selectedUnit=null;a.ready=false;
    if(state.foes.length){const blocker=chooseBlocker(state.foes,a);a.damage+=blocker.power;blocker.damage+=a.power;toast(`${a.name} clashes with ${blocker.name}!`);cleanDead();}
    else{state.enemyLife-=a.power;toast(`${a.name} strikes for ${a.power}.`);}
    checkGameOver();render();
  }
  function chooseBlocker(units,attacker){return units.slice().sort((a,b)=>{
    const aKill=a.power>=attacker.hp-attacker.damage?0:1,bKill=b.power>=attacker.hp-attacker.damage?0:1;
    return aKill-bKill || Math.abs((a.hp-a.damage)-attacker.power)-Math.abs((b.hp-b.damage)-attacker.power) || a.hp-b.hp;
  })[0];}
  function cleanDead(){const survivors=[];for(const u of state.allies){if(u.damage>=u.hp){if(cardBook[u.key])state.grave.push(makeCard(u.key));}else survivors.push(u);}state.allies=survivors;state.foes=state.foes.filter(u=>u.damage<u.hp);}
  function endPlayerTurn(){if(state.finished||state.phase!=='player')return;state.selectedCard=null;state.selectedUnit=null;state.phase='enemy';render();window.setTimeout(enemyTurn,450);}
  function enemyTurn(){if(state.finished)return;state.enemyTurns++;state.enemyMana=Math.min(6,state.enemyMana+1);
    if(state.enemyDeck.length&&state.enemyHand.length<5)state.enemyHand.push(makeEnemy(state.enemyDeck.shift()));
    let played=0;state.enemyHand.sort((a,b)=>b.cost-a.cost);
    while(played<2){const idx=state.enemyHand.findIndex(c=>c.cost<=state.enemyMana);if(idx<0)break;const c=state.enemyHand.splice(idx,1)[0];state.enemyMana-=c.cost;state.foes.push({...c,ready:false,damage:0});played++;}
    // Enemy creatures already in play attack; new arrivals cannot attack this turn.
    for(const f of [...state.foes]){if(state.finished)break;if(!f.ready){f.ready=true;continue;}f.ready=false;
      if(state.allies.length){const blocker=chooseBlocker(state.allies,f);blocker.damage+=f.power;f.damage+=blocker.power;toast(`${f.name} is blocked by ${blocker.name}.`);cleanDead();}
      else{state.playerLife-=f.power;toast(`${f.name} strikes you for ${f.power}.`);}
      checkGameOver();
    }
    if(state.finished){render();return;}
    if(state.enemyTurns%2===0){state.tolls++;state.playerLife-=2;state.foes.forEach(f=>{f.power++;f.hp++;});toast(`THE BELL TOLLS! You lose 2 life; the fen grows stronger.`);if(state.tolls>=3&&state.enemyLife>0){state.finished=true;showEnd(false,'The third toll rolls across the fen. The Keeper still lives.');}}
    if(!state.finished){state.turn++;state.phase='player';state.playerMaxMana=Math.min(6,state.playerMaxMana+1);state.playerMana=state.playerMaxMana;state.allies.forEach(u=>u.ready=true);drawPlayer(false);}
    checkGameOver();render();
  }
  function checkGameOver(){if(state.enemyLife<=0){state.enemyLife=0;state.finished=true;showEnd(true,'You break the relic before the third toll. The fen finally falls quiet.');}
    else if(state.playerLife<=0){state.playerLife=0;state.finished=true;showEnd(false,'The marsh claims another traveler. The Bell-Keeper remains.');}}
  function showEnd(win,copy){if(state.modalMode==='end')return;state.modalMode='end';window.setTimeout(()=>{if(state.modalMode!=='end')return;$('modalEyebrow').textContent=win?'CHALLENGE CLEARED':'CHALLENGE FAILED';$('modalTitle').textContent=win?'The bell is silent.':'Lost to the fen.';$('modalBody').innerHTML=`<div class="game-over"><div class="sigil">${win?'✦':'◉'}</div><p>${copy}</p></div>`;$('modalActions').innerHTML='<button class="end-turn" id="restartGame">PLAY AGAIN <span>↻</span></button>';openModal();$('restartGame').addEventListener('click',()=>location.reload());},250);}
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=window.setTimeout(()=>el.classList.remove('show'),1900);}
  function openModal(){ $('modalBackdrop').classList.remove('hidden'); }
  function closeModal(){if(state.modalMode==='end')return;$('modalBackdrop').classList.add('hidden');state.modalMode='';}
  function showRules(){state.modalMode='rules';$('modalEyebrow').textContent='FIELD NOTES · CHAPTER 04';$('modalTitle').textContent='How to play';$('modalBody').innerHTML='<p><b>Take your turn:</b> You gain one mana each turn (up to 6). Click a card in your hand, then choose PLAY or CAST. Creatures enter tired and can attack next turn.</p><p><b>Combat:</b> Select a ready creature and press ATTACK. If the Keeper has a creature, it blocks automatically; otherwise your creature hits the Keeper directly. The Keeper attacks in the same way.</p><p><b>New mechanic — Echo:</b> When an Echo creature falls, it enters your graveyard. Open GRAVEYARD to cast it one more time for its printed cost +1 mana.</p><p><b>Challenge:</b> Every second enemy turn the bell tolls, dealing 2 damage to you and strengthening the Keeper’s creatures. Defeat the Keeper before the third toll.</p>';$('modalActions').innerHTML='<button class="end-turn" id="modalOkay">GOT IT <span>→</span></button>';openModal();$('modalOkay').addEventListener('click',closeModal);}
  function showGraveyard(){state.modalMode='grave';$('modalEyebrow').textContent='YOUR GRAVEYARD';$('modalTitle').textContent='Echoes in the deep';const echoes=state.grave.filter(c=>c.echo&&!state.echoed.includes(c.id));
    if(!state.grave.length)$('modalBody').innerHTML='<div class="grave-empty">Nothing rests here yet.</div>';
    else if(!echoes.length)$('modalBody').innerHTML=`<p>${state.grave.length} card${state.grave.length===1?'':'s'} lie in your graveyard. No unused Echo cards remain.</p>`;
    else $('modalBody').innerHTML=`<p>Choose an Echo to cast once more for <b>+1 mana</b>.</p><div class="grave-list">${echoes.map(c=>`<div class="grave-entry"><span>${c.art} &nbsp; ${c.name} · ${c.cost+1} mana</span><button data-echo="${c.id}" ${state.playerMana<c.cost+1||state.phase!=='player'?'disabled':''}>ECHO BACK</button></div>`).join('')}</div>`;
    $('modalActions').innerHTML='<button class="tip-cancel" id="modalOkay">CLOSE</button>';openModal();$('modalOkay').addEventListener('click',closeModal);
    document.querySelectorAll('[data-echo]').forEach(btn=>btn.addEventListener('click',()=>castEcho(Number(btn.dataset.echo))));
  }
  function castEcho(id){const c=state.grave.find(x=>x.id===id);if(!c||!c.echo||state.echoed.includes(c.id)||state.playerMana<c.cost+1||state.phase!=='player'||state.finished)return;
    state.playerMana-=c.cost+1;state.echoed.push(c.id);state.grave=state.grave.filter(x=>x.id!==id);const copy=makeCard(c.key);copy.echo=false;copy.text='Returned from the deep.';state.allies.push({...copy,ready:false,damage:0,maxHp:copy.hp});$('modalBackdrop').classList.add('hidden');state.modalMode='';toast(`${c.name} answers its Echo.`);render();
  }
  $('endTurn').addEventListener('click',endPlayerTurn);$('graveButton').addEventListener('click',showGraveyard);$('rulesButton').addEventListener('click',showRules);$('modalClose').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&state.phase==='player'&&!state.finished&&state.modalMode==='')endPlayerTurn();});
  init();
})();

